const CH = JSON.parse($env.MOS_CHANNELS || '{}');
const p = $json.payload;
const ch = CH[p.channel] || {};
const mode = p.schedule?.mode || 'now';
const limit = ch.rate_limit || {};

// Pacing windows by channel kind. An organic feed tolerates one post a day; a messaging
// channel tolerates more; a marketplace listing is effectively unlimited.
const MIN_GAP_MIN = { social_consumer: 240, social_professional: 360, owned: 120, messaging: 5, local: 720, commerce: 1, paid: 60 };
const gap = MIN_GAP_MIN[ch.kind] ?? 120;

return [{ json: {
  mode,
  requested_at: p.schedule?.at || null,
  min_gap_minutes: gap,
  daily_cap: limit.per_day ?? null,
  channel: p.channel,
  timezone: p.schedule?.timezone || 'UTC',
  supports_native_scheduling: ch.supports?.scheduling === true
} }];
